          const cx = el.x + el.w / 2
          const cy = el.y + el.h / 2
          const rx = Math.abs(el.w) / 2 + padding
          const ry = Math.abs(el.h) / 2 + padding
          const dx = wx - cx
          const dy = wy - cy
          return (dx * dx) / (rx * rx) + (dy * dy) / (ry * ry) <= 1.2
